package cz.chap.fakturka

object AppInfo {
    /** Version of this build, generated by Gradle from `-Pfakturka.version`; "dev" when the resource is missing. */
    val VERSION: String by lazy {
        AppInfo::class.java.getResourceAsStream("/fakturka/version.properties")?.use { stream ->
            java.util.Properties().apply { load(stream) }.getProperty("version")
        } ?: "dev"
    }

    /** GitHub repository that publishes the releases. */
    const val REPOSITORY = "chapcz/fakturka"
}
